export async function checkXYZMatrix({state,passed,assert,delay}) {
    const {createEmptyWorkspace,getActiveWorkspace,syncStateToActiveWorkspace,applyWorkspaceToState,buildPersistedState}=await import('/extensions/clab/components/ui_state.js');
    const {matrixCells,matrixOutput}=await import('/extensions/clab/components/workspace_modes/xy_model.js');
    const {parameterValue}=await import('/extensions/clab/components/workspace_modes/task_model.js');
    const {pushPreviewHistoryEntry,captureCardInputSnapshot}=await import('/extensions/clab/components/modules/media_types/media_utils.js');
    const nodes=[{id:110,title:'XYZ参数',widgets:[{name:'steps',label:'步数',type:'number',value:20},{name:'sampler',label:'采样器',type:'combo',value:'Euler',options:{values:['Euler','DPM']}},{name:'cfg',label:'CFG',type:'number',value:7},{name:'text',label:'正向提示词',type:'customtext',value:'workflow forest, soft lighting\nwide shot'},{name:'negative',label:'负向提示词',type:'customtext',value:'blurry, low quality\nkeep details'},{name:'enabled',label:'开关',type:'toggle',value:true}]},{id:111,title:'XYZ输出',type:'SaveImage',widgets:[]}];
    const panel=document.querySelector('#clab-panel'),q=selector=>panel.querySelector(selector),popup=()=>document.querySelector('.clab-xy-values:popover-open'),close=()=>document.querySelector('.clab-module-binding-popover:popover-open')?.querySelector('.clab-xy-popup-close').click();
    syncStateToActiveWorkspace();const original=getActiveWorkspace(),workspaces=[...state.workspaces],execute=window.CLab.executeTasks;
    const seed=(name,x,z={})=>createEmptyWorkspace(name,{cards:[],view:{mode:'xy',xy:{x,y:{bindings:['110||sampler'],values:['Euler','DPM']},z,outputNodeId:'111'}}});
    const numeric=seed('XYZ层测试',{bindings:['110||steps'],values:[20,30]});let demo=numeric,queue=[];
    const show=workspace=>{demo=workspace;for(const node of nodes)if(!window.testApp.graph._nodes.includes(node))window.testApp.graph._nodes.push(node);if(!state.workspaces.includes(demo))state.workspaces.push(demo);applyWorkspaceToState(demo);document.dispatchEvent(new Event('clab_render_ui'));};
    const change=(element,value)=>{element.value=value;element.dispatchEvent(new Event('change',{bubbles:true}));};
    const bind=(name,key)=>{q(`[data-xy-bind="${name}"]`).click();const p=document.querySelector('.clab-module-binding-popover:popover-open');p.querySelector('button[data-xy-node="110"]').click();p.querySelector(`[data-xy-parameter="${key}"]`).click();close();};
    const orientation=value=>q(`[data-xy-origin="${value}"]`).click();
    const option=value=>document.querySelector(`.clab-xy-options:popover-open [data-xy-option="${value}"]`).click();
    const display=value=>{const button=q('[data-xy-toggle-layers]');if(button.getAttribute('aria-pressed')!==String(value==='all'))button.click();};
    const visible=()=>[...panel.querySelectorAll('.clab-cards-wrapper>.clab-card:not([hidden])')];
    try{
        show(numeric);const oldIds=state.cards.map(card=>card.id);assert(oldIds.length===4&&q('.axis-z')&&q('[data-xy-toggle-layers]').getAttribute('aria-pressed')==='false','Z axis is missing or its layer toggle defaults to enabled');assert(visible().every(card=>getComputedStyle(card,'::before').borderTopColor==='rgb(68, 68, 68)'),'ungenerated XYZ cells have no visible frame');
        for(const origin of ['top','bottom']){orientation(origin);const z=q('.axis-z i').getBoundingClientRect(),x=q('.axis-x i').getBoundingClientRect(),y=q('.axis-y i').getBoundingClientRect();assert(z.left<y.left&&z.top<x.top&&Math.abs(z.right-y.left)<2&&Math.abs(z.bottom-x.top)<2,'Z line does not start at the XY intersection and extend upper-left');}
        bind('z','110||cfg');let xy=numeric.view.xy;assert(xy.z.enabled&&xy.z.values.join(',')==='7'&&state.cards.length===4&&oldIds.every(id=>state.cards.some(card=>card.id===id)),'first Z binding lost existing XY tasks instead of adopting workflow values');
        q('.axis-z').click();assert(popup()?.getAttribute('aria-label')==='Z轴设置'&&!popup().querySelector('select,input[type=checkbox],[data-xy-axis-setting]')&&!popup().textContent.includes('显示方式')&&!popup().textContent.includes('运行范围'),'Z settings retained unrelated controls instead of matching the X/Y value editor');
        change(popup().querySelector('[data-xy-values=z]'),'[5,7,9]');close();assert(state.cards.length===12&&visible().length===4&&xy.z.current===1,'Z values did not create separate layers while keeping the previously selected workflow value');
        for(const origin of ['top','bottom']){
            orientation(origin);
            const title=q('.clab-xy-layer-title'),r=title.getBoundingClientRect(),binding=q(`[data-xy-bind="${origin==='bottom'?'y':'z'}"]`).getBoundingClientRect();
            assert(Math.abs((r.top+r.bottom-binding.top-binding.bottom)/2)<2&&Math.abs(parseFloat(getComputedStyle(title).fontSize)/xy.zoom-16)<.1,'layer title is too small or not aligned to the correct binding summary');
            const summary=q('[data-xy-bind=z]').getBoundingClientRect(),button=q('[data-xy-toggle-layers]').getBoundingClientRect();
            assert(button.right<summary.left&&Math.abs(button.height-summary.height)<1.5&&Math.abs(button.width-button.height)<1&&Math.abs(button.top-summary.top)<1.5,'Z display toggle is not square, equally tall and aligned to the left of its binding summary');
        }
        const sameXY=matrixCells(state.cards,xy).filter(cell=>cell.x===0&&cell.y===0).sort((a,b)=>a.z-b.z),images=[];
        for(const cell of sameXY){const area=matrixOutput(cell.card,xy);for(let run=0;run<2;run++)pushPreviewHistoryEntry(area,`/view?filename=xyz-${cell.z}-${run}.png`,{run:{id:`xyz-${cell.z}-${run}`,order:run+1,areaIds:[area.id]},inputSnapshot:captureCardInputSnapshot(cell.card)});window._clabSurgicallyUpdateArea(area.id);images.push(q(`[data-card-id="${cell.card.id}"] img`));}
        await delay(100);const camera=JSON.stringify([xy.panX,xy.panY,xy.zoom]);state.selectedAreaIds=[sameXY[1].card.xyOutputId];q('[data-xy-z-layer="0"]').click();
        assert(visible().length===4&&visible().every(element=>parameterValue(state.cards.find(card=>card.id===element.dataset.cardId),'110||cfg')===5)&&state.selectedAreaIds.length===0&&JSON.stringify([xy.panX,xy.panY,xy.zoom])===camera,'switching Z retained hidden selections, moved the camera or mixed layers');
        q('[data-xy-z-layer="1"]').click();assert(sameXY.every((cell,index)=>q(`[data-card-id="${cell.card.id}"] img`)===images[index]),'Z switching rebuilt an existing output image');
        window.CLab.executeTasks=tasks=>{queue=tasks;};q('[data-xy-run]').click();assert(queue.length===4&&q('[data-xy-run]').textContent.includes('运行 · 4 项')&&queue.every(task=>parameterValue(state.cards.find(card=>card.id===task.cardId),'110||cfg')===7),'default XYZ run included another Z layer');
        q('[data-xy-run-options]').click();assert(document.querySelectorAll('.clab-xy-options:popover-open [data-xy-option]').length===1,'run menu should offer one all-layer command');option('all');assert(queue.length===12&&q('[data-xy-run]').textContent.includes('运行 · 4 项'),'all-layer command became a persistent run mode or omitted hidden layers');
        state.selectedAreaIds=[sameXY[1].card.xyOutputId];q('[data-xy-run]').click();assert(queue.length===1&&queue[0].cardId===sameXY[1].card.id,'selected XYZ run included unselected cells');state.selectedAreaIds=[];
        state.selectedAreaIds=[sameXY[1].card.xyOutputId];q('[data-xy-run-options]').click();option('all');assert(queue.length===12,'all-layer command incorrectly obeyed a local selection');state.selectedAreaIds=[];
        display('all');assert(visible().length===12&&panel.querySelectorAll('.clab-xy-layer-axes').length===3&&panel.querySelectorAll('.clab-xy-layer-title').length===3,'flat Z mode did not display one XY coordinate system per layer');q('[data-xy-run]').click();assert(queue.length===4,'flat display changed default execution to all layers');
        display('single');bind('z','110||cfg');assert(!xy.z.enabled&&!q('[data-xy-run-options]')&&visible().length===4&&state.cards.length===12,'unbinding Z removed archived tasks or left its run menu enabled');
        bind('z','110||cfg');q('.axis-z').click();change(popup().querySelector('[data-xy-values=z]'),'[5,7,9]');close();assert(state.cards.length===12&&sameXY.every(cell=>matrixOutput(cell.card,xy).history.length===2),'rebinding Z duplicated tasks or discarded their histories');
        passed.push('XYZ canvas axis binds and picks parameters, creates independent layers, preserves media and histories, and runs all/current/selected combinations');
        passed.push('Z settings only edit values; its square layer toggle and split-run menu preserve current-layer defaults and title alignment in both orientations');

        const many=seed('Z多取值测试',{bindings:['110||steps'],values:[20]},{enabled:true,bindings:['110||cfg'],values:[1,2,3,4,5,6,7,8,9]});many.view.xy.y.values=['Euler'];show(many);
        const length=q('.axis-z').xyPosition.width;q('[data-xy-z-layer="8"]').click();assert(q('.axis-z').xyPosition.width===length&&q('.clab-z-more'),'many Z values changed the axis length or omitted its full-list entry');
        q('.clab-z-more').click();assert(document.querySelectorAll('.clab-xy-options:popover-open [data-xy-option]').length===9,'Z ellipsis did not expose every layer');option('4');assert(many.view.xy.z.current===4&&q('.axis-z').xyPosition.width===length,'full-list Z selection failed or moved the short-axis endpoint');

        const uniform=seed('统一取值测试',{bindings:['110||steps'],values:[20,30]});uniform.view.xy.y={bindings:['110||enabled'],values:[true,false]};show(uniform);
        q('.axis-x').click();const numericInput=popup().querySelector('[data-xy-values=x]');assert(popup().querySelectorAll('textarea').length===1&&!popup().textContent.includes('显示名称'),'numeric editor retained display names or multiple inputs');
        change(numericInput,'20,30\n40，50');assert(uniform.view.xy.x.values.join(',')==='20,30,40,50'&&numericInput.isConnected,'numeric batch did not mix commas and newlines or rebuilt its editor');change(numericInput,'20,invalid');assert(uniform.view.xy.x.values.length===4&&popup().querySelector('[role=status]').textContent.includes('有效数字'),'invalid numeric batch partially changed its axis');
        popup().querySelector('[data-xy-value-tab=order]').click();assert(!popup().querySelector('[data-xy-value-page=input]').hidden&&popup().querySelector('[data-xy-value-page=order]').hidden&&document.activeElement===numericInput,'invalid draft entered sorting or lost its input focus');
        numericInput.value='20,30,40';numericInput.dispatchEvent(new Event('input',{bubbles:true}));assert(popup().querySelector('[data-xy-value-count]').textContent==='3'&&uniform.view.xy.x.values.length===4,'live draft count mutated the matrix before input was applied');
        popup().querySelector('[data-xy-value-tab=order]').click();assert(popup().querySelectorAll('[data-xy-order-index]').length===3&&uniform.view.xy.x.values.length===3&&popup().querySelector('[data-xy-value-page=input]').hidden,'sorting did not apply the complete draft or render its parsed values');
        popup().querySelector('[data-xy-value-tab=input]').click();assert(popup().querySelector('[data-xy-values=x]')===numericInput&&numericInput.value==='20,30,40','switching tabs rebuilt or rewrote the input draft');close();
        q('.axis-y').click();const booleanOptions=popup().querySelectorAll('[data-xy-choice]');assert(booleanOptions.length===2&&[...booleanOptions].every(input=>input.checked)&&!popup().textContent.includes('显示名称'),'boolean controls changed or retained display names');booleanOptions[1].click();assert(uniform.view.xy.y.values.length===1&&uniform.view.xy.y.values[0]===true,'boolean checkbox did not remove the selected value');popup().querySelector('[data-xy-value-tab=order]').click();assert(popup().querySelectorAll('[data-xy-order-index]').length===1&&popup().querySelector('[data-xy-order-index]').textContent==='true','boolean sorting lost its typed selection');popup().querySelector('[data-xy-value-tab=input]').click();assert(popup().querySelectorAll('[data-xy-choice]').length===2&&popup().querySelector('[data-xy-choice="0:0"]')===booleanOptions[0]&&booleanOptions[0].checked&&!booleanOptions[1].checked,'tab switching removed available choices or lost checkbox states');close();
        show(numeric);q('.axis-y').click();assert(popup().querySelectorAll('[data-xy-choice]').length===2&&!popup().textContent.includes('显示名称'),'fixed options changed or retained display names');close();

        const first='a forest, a small cabin, and a river\nkeep all punctuation <safe text>',second='a city, rainy streets, cinematic lights\nwide angle';
        const prompts=seed('提示词轴测试',{bindings:['110||text'],values:[first,second]});show(prompts);xy=prompts.view.xy;
        const tick=q('.clab-axis-label[data-xy-edit-values=x]');assert(tick.textContent===first.replace(/\s+/g,' ')&&tick.title===first&&tick.style.maxWidth.includes('308'),'text ticks added an identifier, lost their full tooltip or exceeded column width');
        tick.click();assert(popup().querySelectorAll('textarea').length===1&&!popup().textContent.includes('显示名称')&&!popup().querySelector('img,[data-xy-text-add]'),'text editor retained aliases, row controls or unsafe HTML');
        const input=popup().querySelector('[data-xy-values=x]'),full=first+'\nextra detail, another comma';assert(JSON.parse(input.value)[0]===first,'opening the unified editor split existing multiline prompts');
        change(input,'forest, soft light\n\ncity, rainy streets');assert(xy.x.values.length===2&&xy.x.values[0]==='forest, soft light'&&xy.x.values[1]==='city, rainy streets'&&input.isConnected,'text batches split commas, kept blank lines or rebuilt their editor');
        change(input,'["unfinished"');assert(xy.x.values.length===2&&popup().querySelector('[role=status]').textContent.includes('JSON'),'invalid JSON replaced the previous valid matrix');
        change(input,JSON.stringify([full,second]));close();q('.clab-axis-label[data-xy-edit-values=x][data-xy-tick="1"]').click();assert(document.activeElement===popup().querySelector('[data-xy-values=x]'),'clicking a text tick did not focus its batch editor');close();
        bind('x','110||cfg');q('.axis-x').click();change(popup().querySelector('[data-xy-values=x]'),JSON.stringify([[full,9],[second,7]]));assert(xy.x.values[0][0]===full&&xy.x.values[0][1]===9,'mixed text/numeric batch lost typed group values');close();
        bind('z','110||negative');q('.axis-z').click();const negative=popup().querySelector('[data-xy-values=z]'),negativeText='blurry, low resolution\nnegative prompt';change(negative,JSON.stringify([negativeText]));close();const zTick=q('.clab-z-tick');assert(zTick.textContent===negativeText.replace(/\s+/g,' ')&&zTick.title===negativeText&&getComputedStyle(zTick.querySelector('span')).textOverflow==='ellipsis','Z ticks retained identifiers or lost full content/ellipsis styling');
        const saved=buildPersistedState().workspaces.find(workspace=>workspace.id===prompts.id);assert(saved.view.xy.x.values[0][0]===full&&saved.view.xy.z.values[0]===negativeText&&!('labels' in saved.view.xy.z),'full text batches were not persisted or display aliases returned');
        passed.push('XYZ text/numeric axes share one batch editor with actual-content ellipsis, preserve typed JSON values and retain fixed-option/boolean checklists');
        passed.push('axis value tabs preview valid draft counts without creating tasks, reject invalid sorting and preserve input/checkbox DOM between pages');
        window.showXYZDemo=()=>{show(numeric);window.xyzModeDemo=numeric;};window.showXYZPromptDemo=()=>{show(prompts);window.xyzPromptDemo=prompts;};
    }finally{
        close();window.CLab.executeTasks=execute;state.workspaces=workspaces;applyWorkspaceToState(original);document.dispatchEvent(new Event('clab_render_ui'));for(const node of nodes){const index=window.testApp.graph._nodes.indexOf(node);if(index>=0)window.testApp.graph._nodes.splice(index,1);}
    }
    await delay(60);
}
